"""Serialize independent manual corrections for archive extension ranks 42-50."""
import hashlib
import json
from pathlib import Path
from urllib.parse import urlsplit

BASE=Path(__file__).resolve().parents[2]
OUT=BASE/'outputs'
QA=Path(__file__).resolve().parent
COMMENTS={
42:dict(verdict='SUPPORTED_WITH_REQUIREMENT_QUALIFICATION',corrections=[{'field':'requirements','text':'Add Node.js for validators and an OS-enforced sandbox with sanitized environment, networking disabled and resource/write limits before executing any target-controlled tests. Tool-using subagents alone do not provide that boundary.','readme_lines':[86,97]},{'field':'decision','text':'Keep REUSE explicitly limited to reviewed methodology/ledger/schema as already described in the acceptance criterion; it is not approval to install/execute the skill or a completed security certification.','readme_lines':[9,22]}],decision_change=False),
43:dict(verdict='SUPPORTED_WITH_MATERIAL_SCOPE_AND_BUDGET_QUALIFICATIONS',corrections=[{'field':'requirements','text':'Separate local d3k requirements from the remote/sandbox launcher, which the README limits to macOS, with Vercel login/access and additional tools. Do not imply Windows supports the sandbox mode.','readme_lines':[74,91]},{'field':'risk','text':'The source has inconsistent budget descriptions: an earlier fx section says a non-renewing $5 session cap, while the newer Eve default section says no session spending cap. Budget default must remain UNKNOWN/harness-dependent until source-code/configuration review and a bounded test; do not claim a safe cap from this README.','readme_lines':[85,89],'additional_readme_lines':[128,140]},{'field':'minimum_acceptance','text':'The live timeline is bounded to 5,000 events/8 MiB and disappears on exit; body/redaction capture is selective and best effort. Add evidence-gap/eviction handling and an explicitly authorized durable evidence export rather than treating d3k as a durable audit ledger.','readme_lines':[46,58]}],decision_change=False),
44:dict(verdict='SUPPORTED_WITH_LICENSE_SCOPE_CORRECTION',corrections=[{'field':'license_scope','text':'Use: MIT for inspected BlazeDiff code; embedded MILO weights are Apache-2.0; original reference-code terms and notices are separately described. Algorithm/dependency/commercial-rights clearance remains NOT_AUDITED. The reference MATLAB SSIM/MS-SSIM restrictions must not be blindly applied to the independently MIT-claimed implementation, or ignored for imported reference code.','readme_lines':[107,124],'supplemental_sources':'BLAZEDIFF-SUPPLEMENTAL-SOURCES.json'},{'field':'risk','text':'Distinguish deterministic core/metric calculations from the optional agent-in-the-loop product. Vendor speed/parity claims and learned perceptual metrics are not independently tested or UX acceptance.','readme_lines':[24,56]}],decision_change=False),
45:dict(verdict='SUPPORTED_NO_SUBSTANTIVE_CORRECTION',corrections=[{'field':'risk','text':'Retain the explicit whole-running-Chrome/logged-in-user boundary and DEFER decision. The current README says Browser Harness is the engine inside Browser Use; installing both is not an independent engine comparison. Its benchmark used a shared fresh cloud browser, not each tool\'s default local session.','readme_lines':[3,18],'additional_readme_lines':[61,91]}],decision_change=False),
46:dict(verdict='SUPPORTED_WITH_RISK_WORDING_QUALIFICATION',corrections=[{'field':'risk','text':'Replace ambiguous URL/ZIP traversal wording with: untrusted file paths, remote URLs and archive contents require validation and resource limits; no specific path-traversal vulnerability was demonstrated. The README expressly states current-process I/O privileges, broad convert(), and narrower convert_local/convert_stream APIs. Narrow APIs are not a sandbox by themselves.','readme_lines':[459,467]},{'field':'requirements','text':'Python 3.10-3.14 is supported by README. Preserve selective extras/plugins-off-by-default and local-only dependencies; image captioning/transcription and Azure conversion paths are remote/billable options.','readme_lines':[26,38],'additional_readme_lines':[92,117]}],decision_change=False),
47:dict(verdict='SUPPORTED_WITH_AUTH_ROUTE_AND_STORAGE_QUALIFICATIONS',corrections=[{'field':'risk','text':'Authentication configuration alone does not close the README\'s default-open Ollama-compatible /api/* routes. Include the documented whitelist restriction and verify unauthenticated access is denied across every exposed route. The host=0.0.0.0/auth-off statement is a pinned README observation, not a current AWE runtime finding.','readme_lines':[98,105]},{'field':'requirements','text':'Default KV/vector/graph/doc-status backends are in-memory with local file persistence and are described as evaluation-only, not production. Storage/model/embedding configuration and reindex/delete behavior need separate acceptance.','readme_lines':[289,299],'additional_readme_lines':[339,343],'additional_readme_line':391}],decision_change=False),
48:dict(verdict='SUPPORTED_WITH_CONCURRENCY_QUALIFICATION',corrections=[{'field':'requirements','text':'README now lists Windows as well as Linux/macOS/mobile and OS-specific SDK features; do not preserve a Linux-only assumption. It specifies 64-bit Python 3.10-3.14. Writes are single-process exclusive although multiple processes may read.','readme_lines':[36,44],'additional_readme_lines':[57,85]},{'field':'risk','text':'WAL durability/performance claims are source assertions to test, not evidence of PostgreSQL transaction/RLS/auth equivalence. Keep the crash/reopen, isolation and measured-advantage pilot rather than replacing current storage.','readme_lines':[50,59]}],decision_change=False),
49:dict(verdict='SUPPORTED_WITH_LOCAL_DATAFLOW_QUALIFICATION',corrections=[{'field':'risk','text':'Local SDK/index storage does not imply offline inference: source examples still use an LLM API key. Cloud mode also transfers indexing/storage to the vendor; make dataflow, model cost and cloud storage explicit. Subscription-based Claude invocation remains an advertised integration, not an independent grant of provider permission or guaranteed quota.','readme_lines':[84,105],'additional_readme_lines':[179,217]},{'field':'cost','text':'Keep source benchmark/indexing-cost headlines separate from AWE measurements and from cloud/subscription pricing. No quoted savings/cost/accuracy figure has been reproduced in this audit.','readme_lines':[116,165]}],decision_change=False),
50:dict(verdict='SUPPORTED_WITH_GROUNDING_AND_SUPPORT_QUALIFICATIONS',corrections=[{'field':'minimum_acceptance','text':'Explicitly reject/filter extractions whose char_interval is None. The README acknowledges hallucinated extraction from few-shot examples; a valid schema or source-looking text is insufficient. Also test wrong/overlapping spans and factual attributes that go beyond source text.','readme_lines':[106,108],'additional_readme_lines':[153,157]},{'field':'requirements','text':'Do not promise identical schema enforcement across providers: the README says Ollama does not currently support output_schema. Google organization ownership does not mean an officially supported Google product; the disclaimer says otherwise.','readme_lines':[403,405],'additional_readme_lines':[535,541]}],decision_change=False),
}

def main():
    path=OUT/'TECHNICAL-REVIEWS.json'
    rows=json.loads(path.read_text(encoding='utf-8'))
    inventory=[json.loads(x) for x in (OUT/'INVENTORY-ALL.jsonl').read_text(encoding='utf-8').splitlines()]
    byid={x['source_id']:x for x in inventory}
    bad=[]; ids=set()
    for row in rows:
        for sid in row['source_ids']:
            ids.add(sid)
            if sid not in byid: bad.append({'rank':row['rank'],'id':sid,'reason':'ID_MISSING'}); continue
            u=urlsplit(byid[sid]['original_url']); project='/'.join(u.path.strip('/').split('/')[:2]).lower().removesuffix('.git')
            if u.hostname not in ('github.com','www.github.com') or project not in {row['repo'].lower(),row['canonical_repo'].lower()}:
                bad.append({'rank':row['rank'],'id':sid,'reason':'PROJECT_MISMATCH'})
    findings=[]
    for rank,comment in COMMENTS.items():
        row=next(r for r in rows if r['rank']==rank)
        p=BASE/f'work/github-cache/{rank}.json'
        cache=json.loads(p.read_text(encoding='utf-8'))
        readme=next(r for r in cache['resources'] if r['kind']=='readme')
        line_count=len(readme['data']['content'].splitlines())
        for c in comment['corrections']:
            assert c['readme_lines'][1]<=line_count
        findings.append({'rank':rank,'repo':row['canonical_repo'],'head':row['head'],'source_ids':row['source_ids'],'evidence':{'readme_url':readme['url'],'readme_blob':readme['data'].get('sha'),'readme_line_count':line_count,'cache_sha256':hashlib.sha256(p.read_bytes()).hexdigest()},**comment,'runtime':'NOT_RUN','security_audit':'NOT_PERFORMED','awe_acceptance':'NOT_PROVEN'})
    result={'status':'SOURCE_TEXT_REVIEW_COMPLETED_FOR_RANKS_42_TO_50_OVERALL_PARTIAL','checked_at':'2026-11-12','reviewer':'Independent separate agent; same GPT family, cross-family requirement NOT_SATISFIED','reviewed_count':9,'technical_reviews_snapshot_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'archive_linkage_check':{'technical_review_rows':len(rows),'exact_project_review_rows':sum(r['archive_membership']=='EXACT_PROJECT_MATCH' for r in rows),'unique_original_source_ids':len(ids),'architecture_addition_rows':sum(not r['source_ids'] for r in rows),'mismatches':bad,'id_project_match':not bad},'scope':'Pinned cached README/license text for nine added archive candidates; six extra BlazeDiff upstream/license texts. No code installed or executed, no API/model inference, no runtime certification.','findings':findings,'framing':'50 source-linked desk reviews are not 50 runtime or security audits.'}
    (QA/'ARCHIVE-EXTENSION-REVIEW.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    lines=['# Independent review of archive-extension ranks 42-50','','Status: **PARTIAL**. All nine added source-linked reviews were independently checked against their pinned README/license caches. Additional BlazeDiff licensing sources were read separately. No upstream code was executed. The same-family reviewer cannot close the different-model-family gate.','','The nine recommendations are broadly supported; no decision change is required. Apply the qualifications below before presenting the final review. Source-line pointers refer to the immutable README URL recorded for each rank in `ARCHIVE-EXTENSION-REVIEW.json`.','','Independent archive linkage: 50 review entries include 30 exact-project entries linked to **32 distinct original source rows**, plus 20 architecture additions. No ID/project mismatch was found. This does not mean 50 archive tools or 50 runtime audits.','']
    for row in findings:
        lines += [f"## {row['rank']}. {row['repo']}",'',f"[Pinned README]({row['evidence']['readme_url']}). Verdict: `{row['verdict']}`.",'']
        for c in row['corrections']:
            refs=f"README:{c['readme_lines'][0]}-{c['readme_lines'][1]}"
            if 'additional_readme_lines' in c: refs+=f", {c['additional_readme_lines'][0]}-{c['additional_readme_lines'][1]}"
            if 'additional_readme_line' in c: refs+=f", {c['additional_readme_line']}"
            lines += [f"- **{c['field']}**: {c['text']} ({refs})"]
        lines.append('')
    lines += ['BlazeDiff supplemental immutable URLs/blob SHAs and observation limits are in `BLAZEDIFF-SUPPLEMENTAL-SOURCES.json`. The upstream model weight digest was not downloaded/recomputed. No legal clearance, dependency-wide license audit, actual OS compatibility or performance comparison was performed.','','For every added candidate: runtime **NOT_RUN**, security audit **NOT_PERFORMED**, AWE acceptance **NOT_PROVEN**.']
    (QA/'ARCHIVE-EXTENSION-REVIEW.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(json.dumps({'reviewed_count':9,'linkage':result['archive_linkage_check'],'decision_changes':0},ensure_ascii=False))

if __name__=='__main__': main()
